def floor_fonts(s, lo=10.0):
    """Raise px font sizes below lo to lo in a card's HTML and use the Inter stack in chart text (labels never under 10px)."""
    s = s.replace('font-family="sans-serif"', 'font-family="Inter,-apple-system,sans-serif"')

    def f1(m):
        v = float(m.group(2))
        return m.group(1) + (f'{lo:g}' if v < lo else m.group(2)) + 'px'
    s = _re.sub(r'(font-size:\s*)(\d+(?:\.\d+)?)px', f1, s)
    return _re.sub(r'(font:\s*(?:italic\s+)?(?:\d{3}\s+)?)(\d+(?:\.\d+)?)px', f1, s)


def card(body_html, page_no, eyebrow='', title='', cls=''):
    """One printed page (430x830). Body goes inside .col; the page number is pinned in the footer by the CSS.
    cls adds classes to the section (fx, tt, tt2, gloss, or a scope() module class)."""
    head = ''
    if eyebrow:
        head += f'<div class="eyebrow">{eyebrow}</div>'
    if title:
        head += f'<h2 class="head">{title}</h2><div class="rule"></div>'
    c = f'page {cls}'.strip()
    return (f'<section class="{c}" id="p{page_no}"><div class="col">{head}{body_html}</div>'
            f'<div class="pgn">{page_no}</div></section>')


def scope(html, cls, css=''):
    """Tag a card's <section class="page"> with cls and prefix every selector of its inline <style> blocks (and of css,
    added as one more <style> block inside the card) with that class, so a module's CSS cannot leak into other modules'
    pages. cls is one of m1, m2a, m2b, m2c, m2d, m3. css: plain rules only, no @-rules."""
    if '@' in css:
        raise ValueError('scope(): no @-rules in module css')

    def fix(m):
        out = []
        for rule in _re.finditer(r'([^{}]+)\{([^{}]*)\}', m.group(1)):
            sels = []
            for s in rule.group(1).split(','):
                s = s.strip()
                sels.append(('.page.' + cls + s[5:]) if s.startswith('.page') else f'.{cls} {s}')
            out.append(','.join(sels) + '{' + rule.group(2) + '}')
        return '<style>' + ''.join(out) + '</style>'
    if css:
        html = html.replace('</section>', f'<style>{css}</style></section>', 1)
    html = _re.sub(r'<style>(.*?)</style>', fix, html, flags=_re.S)
    return html.replace('<section class="page', f'<section class="page {cls}', 1)


def document(body_html, title, lang='en'):
    """Complete standalone HTML document: ANNUAL_CSS in the head, ANNUAL_DEFS first in the body, cards in one parent."""
    return ('<!DOCTYPE html>\n<html lang="' + _h.escape(lang, quote=True) + '"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width,initial-scale=1">'
            f'<title>{_h.escape(title)}</title><style>{ANNUAL_CSS}</style></head>'
            f'<body class="ar">\n{ANNUAL_DEFS}<div>{body_html}</div></body></html>\n')


# ===================== COMPONENT KIT (shell.py) =====================
# All helpers return HTML strings. Text args are trusted HTML (not escaped). Classes are prefixed k- to avoid clashes.
MLETTERS = 'JFMAMJJASOND'
mletters = MLETTERS
CHIP_WORD = {'strong': 'STRONG', 'mixed': 'MIXED', 'careful': 'CAREFUL'}
_TONES = ('strong', 'mixed', 'careful')


def _ym(ym):
    return int(ym[:4]), int(ym[5:7])


def mname(ym):
    """'2027-01' -> 'Jan 2027'."""
    y, m = _ym(ym)
    return f'{MONTHS[m - 1]} {y}'


def mshort(ym):
    """'2027-01' -> 'Jan'."""
    return MONTHS[_ym(ym)[1] - 1]


def mletter(ym):
    """'2027-01' -> 'J'."""
    return MLETTERS[_ym(ym)[1] - 1]


def mrange(yms):
    """['2026-12','2027-02','2027-03','2027-04'] -> 'Dec 2026, Feb to Apr 2027'. Merges consecutive months, keeps order,
    shows the year when it changes. Empty list -> ''."""
    segs = []
    for ym in yms:
        y, m = _ym(ym)
        idx = y * 12 + m
        if segs and idx == segs[-1][2] + 1:
            segs[-1][1] = ym
            segs[-1][2] = idx
        else:
            segs.append([ym, ym, idx])
    out = []
    for i, (a, b, _) in enumerate(segs):
        ya, yb = _ym(a)[0], _ym(b)[0]
        nxt_year = _ym(segs[i + 1][0])[0] if i + 1 < len(segs) else None
        if a == b:
            out.append(mname(a))
            continue
        left = mname(a) if ya != yb else mshort(a)
        right = mshort(b) if (ya == yb and nxt_year == yb) else mname(b)
        out.append(f'{left} to {right}')
    return ', '.join(out)


def part_label(n, title):
    """Small pill for card() eyebrow: part_label(1, 'Short version') -> 'PART 1 · SHORT VERSION'."""
    return f'<span class="k-part">Part {n} &middot; {title}</span>'


def part_band(n, title, sub=''):
    """Full-width divider band for the first card of a Part."""
    s = f'<small>{sub}</small>' if sub else ''
    return f'<div class="k-band"><b>Part {n}</b><span>{title}</span>{s}</div>'


def chip(tone, text=None):
    """STRONG / MIXED / CAREFUL chip. tone 'strong'|'mixed'|'careful' (other tone = neutral). text overrides the word."""
    t = tone if tone in _TONES else 'note'
    return f'<span class="k-chip k-{t}">{text or CHIP_WORD.get(tone, str(tone).upper())}</span>'


def tile(label, value, sub=''):
    s = f'<div class="k-ts">{sub}</div>' if sub else ''
    return f'<div class="k-tile"><div class="k-tl">{label}</div><div class="k-tv">{value}</div>{s}</div>'


def tiles(items):
    """items: list of (label, value[, sub]) or tile() strings. 2 or 4 items -> 2 columns, else 3 columns."""
    cols = 2 if len(items) in (1, 2, 4) else 3
    body = ''.join(i if isinstance(i, str) else tile(*i) for i in items)
    return f'<div class="k-tiles k-c{cols}">{body}</div>' if items else ''


def _cells(tones, months, highlight, big):
    keys = list(months) if months else list(tones.keys())[:12]
    out = ''
    for ym in keys:
        t = tones.get(ym, 'none')
        t = t if t in _TONES else 'none'
        lab = mshort(ym) if big else mletter(ym)
        hl = ' k-hl' if ym == highlight else ''
        out += f'<div class="k-mc{hl}"><i class="k-{t}"></i><span>{lab}</span></div>'
    return out, len(keys)


def mini_strip(tones_by_month, highlight=None, months=None):
    """Compact 12-box strip, month letters under each box. highlight='YYYY-MM' outlines one month.
    months=list of ym restricts/orders the boxes (missing ones draw grey). Empty input -> ''."""
    c, n = _cells(tones_by_month, months, highlight, False)
    return f'<div class="k-mini" style="grid-template-columns:repeat({n},1fr)">{c}</div>' if n else ''


def strip_big(tones_by_month, highlight=None, months=None):
    """Large strip: tall boxes, 3-letter month names, and run labels under it ('Jul to Nov' or the tone word)."""
    c, n = _cells(tones_by_month, months, highlight, True)
    if not n:
        return ''
    keys = list(months) if months else list(tones_by_month.keys())[:12]
    runs, i = [], 0
    while i < n:
        t = tones_by_month.get(keys[i], 'none')
        j = i
        while j + 1 < n and tones_by_month.get(keys[j + 1], 'none') == t:
            j += 1
        runs.append((t, i, j))
        i = j + 1
    rl = ''
    for t, a, b in runs:
        t = t if t in _TONES else 'none'
        lab = '' if t == 'none' else (f'{mshort(keys[a])} to {mshort(keys[b])}' if b - a >= 2 else (CHIP_WORD[t].title() if b > a else ''))
        rl += f'<div class="k-run k-r-{t}" style="grid-column:span {b - a + 1}">{lab}</div>'
    return (f'<div class="k-big" style="grid-template-columns:repeat({n},1fr)">{c}</div>'
            f'<div class="k-runs" style="grid-template-columns:repeat({n},1fr)">{rl}</div>')


def counts(tones):
    """Three count tiles computed from {ym: tone}."""
    v = list(tones.values())
    def one(t, w):
        n = v.count(t)
        return (f'<div class="k-cnt k-cn-{t}"><b>{n}</b><span>{w} {"month" if n == 1 else "months"}</span></div>')
    return '<div class="k-cnts">' + one('strong', 'strong') + one('mixed', 'mixed') + one('careful', 'careful') + '</div>'


def answer_row(topic, tone, lead_line, best_months_text, careful_months_text, tones_by_month):
    """One row of 'Your 5 answers': topic + chip, lead line, Best / Careful lines, mini strip."""
    best = f'<div class="k-al"><b>Best</b> {best_months_text or "none this year"}</div>'
    care = f'<div class="k-al"><b>Careful</b> {careful_months_text or "none this year"}</div>'
    return (f'<div class="k-ans"><div class="k-ah"><span class="k-at">{topic}</span>{chip(tone)}</div>'
            f'<div class="k-lead">{lead_line}</div>{best}{care}{mini_strip(tones_by_month)}</div>')


def qblock(question, tone, lines):
    """Question block: question + tone chip, then labelled lines. lines: dict with any of Do, Watch, Why, When."""
    rows = ''.join(f'<div class="k-ql"><b>{k}</b><span>{lines[k]}</span></div>' for k in ('Do', 'Watch', 'Why', 'When') if lines.get(k))
    return f'<div class="k-q k-q-{tone if tone in _TONES else "note"}"><div class="k-qh"><span>{question}</span>{chip(tone)}</div>{rows}</div>'


def callout(title, text, kind='note'):
    """kind: note (gold), good (green), careful (terracotta)."""
    cls = {'note': '', 'good': ' good', 'careful': ' terra'}.get(kind, '')
    return f'<div class="callout{cls}"><div class="ch">{title}</div><p>{text}</p></div>'


def tl_bar(segments):
    """Horizontal timeline bar. segments=[(label, start, end, kind)] or with a 5th weight number; kind strong|mixed|careful|note.
    Segments are equal width unless weights are given. Start/end are date labels shown under each boundary."""
    if not segments:
        return ''
    segs = ''
    dates = ''
    for s in segments:
        label, a, b, kind = s[:4]
        w = s[4] if len(s) > 4 else 1
        kind = kind if kind in _TONES else 'note'
        segs += f'<div class="k-sg k-{kind}" style="flex:{w}"><span>{label}</span></div>'
        dates += f'<div class="k-sd" style="flex:{w}"><span>{a}</span></div>'
    end = segments[-1][2]
    return f'<div class="k-tlb"><div class="k-tlbar">{segs}</div><div class="k-tld">{dates}<em>{end}</em></div></div>'


def area_table(rows):
    """Five-row table for month cards. rows: [(area, tone, one_line)] (any number of rows)."""
    body = ''.join(f'<div class="k-ar"><b>{a}</b>{chip(t)}<span>{l}</span></div>' for a, t, l in rows)
    return f'<div class="k-area">{body}</div>' if rows else ''


def gloss_term(term, plain, yours='', see_page=None):
    y = f'<div class="k-gy"><b>Yours</b> {yours}</div>' if yours else ''
    p = f'<div class="k-gp">See page {see_page}</div>' if see_page else ''
    return f'<div class="k-gl"><div class="k-gt">{term}</div><div class="k-gd">{plain}</div>{y}{p}</div>'


def gloss_two_col(items):
    """items: list of gloss_term() strings or (term, plain[, yours[, see_page]]) tuples."""
    body = ''.join(i if isinstance(i, str) else gloss_term(*i) for i in items)
    return f'<div class="k-g2">{body}</div>' if items else ''


def table(headers, rows, small=False):
    """Compact table (uses .tw). rows: list of lists of cell html."""
    h = ''.join(f'<th>{x}</th>' for x in headers)
    b = ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows)
    return f'<table class="tw{" k-sm" if small else ""}"><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table>'


def steps(items):
    """Numbered rows. items: strings or (bold, text) tuples."""
    out = ''
    for i, it in enumerate(items, 1):
        t = f'<b>{it[0]}</b> {it[1]}' if isinstance(it, tuple) else it
        out += f'<div class="sr"><div class="num">{i}</div><div class="st">{t}</div></div>'
    return f'<div class="scores">{out}</div>' if items else ''


_SCORE = {'strong': 1.0, 'mixed': .58, 'careful': .22}
_COL = {'strong': '#3E7D5A', 'mixed': '#C9A34E', 'careful': '#B4572B', 'none': '#D9CFBB'}


def _vals(tones):
    ks = list(tones.keys())[:12]
    return [tones.get(k) if tones.get(k) in _COL else 'none' for k in ks] or ['none'] * 12   # unknown tone draws neutral


def chapter_graphic(kind, tones_by_month):
    """~90px inline SVG exhibit. kind: career | money | marriage | luck | strengths. Empty/unknown input draws neutral shapes."""
    v = _vals(tones_by_month)
    n = len(v)
    W, H = 380, 90
    sc = [_SCORE.get(t, .4) for t in v]
    b = ''
    if kind == 'career':   # ladder: each month a step, height = tone, stepped line on top
        bw = W / n
        pts = ''
        for i, (t, s) in enumerate(zip(v, sc)):
            h = 12 + s * 62
            x = i * bw
            b += f'<rect x="{x + 2:.1f}" y="{80 - h:.1f}" width="{bw - 4:.1f}" height="{h:.1f}" rx="3" fill="{_COL[t]}" fill-opacity=".85"/>'
            pts += f'{max(x, 1):.1f},{80 - h:.1f} {min(x + bw, W - 1):.1f},{80 - h:.1f} '   # inset 1: the 1.4 stroke stays inside the viewBox
        b += f'<polyline points="{pts}" fill="none" stroke="#B9862E" stroke-width="1.4"/>'
    elif kind == 'money':  # in (up) / out (down) columns around a mid line
        bw = W / n
        b += f'<line x1="0" x2="{W}" y1="45" y2="45" stroke="#B9862E" stroke-width="1"/>'
        for i, (t, s) in enumerate(zip(v, sc)):
            x = i * bw + bw * .2
            up, dn = 6 + s * 34, 6 + (1 - s) * 34
            b += f'<rect x="{x:.1f}" y="{45 - up:.1f}" width="{bw * .6:.1f}" height="{up:.1f}" rx="2" fill="#3E7D5A" fill-opacity=".8"/>'
            b += f'<rect x="{x:.1f}" y="46" width="{bw * .6:.1f}" height="{dn:.1f}" rx="2" fill="#B4572B" fill-opacity=".55"/>'
    elif kind == 'marriage':  # mood line with soft area and dots
        bw = W / n
        pts = [(i * bw + bw / 2, 76 - s * 60) for i, s in enumerate(sc)]
        d = 'M' + ' L'.join(f'{x:.1f} {y:.1f}' for x, y in pts)
        b += f'<path d="{d} L{pts[-1][0]:.1f} 82 L{pts[0][0]:.1f} 82 Z" fill="#EAD9AE" fill-opacity=".55"/>'
        b += f'<path d="{d}" fill="none" stroke="#B9862E" stroke-width="1.6" stroke-linejoin="round"/>'
        for (x, y), t in zip(pts, v):
            b += f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4.2" fill="{_COL[t]}" stroke="#fff" stroke-width="1.2"/>'
    elif kind == 'luck':   # dial: three arcs plus a needle at the average score
        import math
        cx, cy, r = W / 2, 82, 64
        def arc(a0, a1, col):
            x0, y0 = cx + r * math.cos(math.pi * (1 - a0)), cy - r * math.sin(math.pi * (1 - a0))
            x1, y1 = cx + r * math.cos(math.pi * (1 - a1)), cy - r * math.sin(math.pi * (1 - a1))
            return f'<path d="M{x0:.1f} {y0:.1f} A{r} {r} 0 0 1 {x1:.1f} {y1:.1f}" fill="none" stroke="{col}" stroke-width="9" stroke-linecap="round"/>'
        b += arc(0.02, .32, '#B4572B') + arc(.36, .64, '#C9A34E') + arc(.68, .98, '#3E7D5A')
        avg = sum(sc) / len(sc) if tones_by_month else .5
        a = math.pi * (1 - avg)
        b += f'<line x1="{cx}" y1="{cy}" x2="{cx + 52 * math.cos(a):.1f}" y2="{cy - 52 * math.sin(a):.1f}" stroke="#1B1D2A" stroke-width="2.4" stroke-linecap="round"/><circle cx="{cx}" cy="{cy}" r="5" fill="#B9862E"/>'
    else:                  # strengths: four horizontal bars (one per quarter of the list)
        for q in range(4):
            seg = sc[q * 3:q * 3 + 3] or [.4]
            s = sum(seg) / len(seg)
            y = 8 + q * 20
            b += f'<rect x="40" y="{y}" width="320" height="11" rx="5.5" fill="#ECE3D3"/><rect x="40" y="{y}" width="{20 + 300 * s:.1f}" height="11" rx="5.5" fill="#C9A34E"/>'
            b += f'<text x="4" y="{y + 9}" font-size="9" fill="#4C4A57" font-family="Inter,sans-serif">Q{q + 1}</text>'
    return f'<div class="k-gx"><svg viewBox="0 0 {W} {H}" width="100%" height="{H}" role="img" aria-label="{kind} exhibit" preserveAspectRatio="xMidYMid meet">{b}</svg></div>'


# ---------- Manglik wheel: 12 circles on an ellipse, the parts where Mars counts in gold, Mars in red ----------
_WHEEL_CAP = ((40, 'Gold circles:'), (51.5, 'the 6 parts where'), (63, 'Mars counts.'), (74.5, 'Red: Mars'))


def _wheel_pos(k):
    a = _m.radians(-90 + 30 * k)
    return 160 + 78 * _m.cos(a), 52 + 78 * _m.sin(a) * .62


def _wheel_viewbox(margin=6):
    """One fixed box that holds all 12 circles even when any of them is the big red one, plus the caption."""
    xs, ys = [], []
    for k in range(12):
        x, y = _wheel_pos(k)
        r = 13 + .4                                  # biggest circle + half the stroke
        xs += [x - r, x + r]; ys += [y - r, y + r]
    for y, t in _WHEEL_CAP:
        w = len(t) * 9 * .55
        xs += [160 - w / 2, 160 + w / 2]; ys += [y - 9 * .8, y + 9 * .3]
    x0, y0, x1, y1 = min(xs) - margin, min(ys) - margin, max(xs) + margin, max(ys) + margin
    return x0, y0, x1 - x0, y1 - y0


def wheel_svg(parts_set, mars_part, width=300):
    """Mars ring. parts_set: the part numbers (1-12) drawn gold; mars_part: the one drawn red (None for no red circle).
    The viewBox is computed from the drawn shapes, so nothing is clipped for any input."""
    s = ''
    for k in range(12):
        x, y = _wheel_pos(k)
        n = k + 1
        on = n in (parts_set or ())
        me = n == mars_part
        fill = '#B4572B' if me else ('#EAD9AE' if on else '#F4EEDF')
        tc = '#fff' if me else '#2A2118'
        s += (f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{13 if me else 11}" fill="{fill}" stroke="#B9862E" stroke-width=".8"/>'
              f'<text x="{x:.1f}" y="{y + 3.5:.1f}" text-anchor="middle" font-size="{9 if me else 10}" font-weight="600" fill="{tc}">{"Ma" if me else n}</text>')
    s += ''.join(f'<text x="160" y="{y}" text-anchor="middle" font-size="9" fill="#8A7B63">{t}</text>' for y, t in _WHEEL_CAP)
    x0, y0, w, h = _wheel_viewbox()
    return (f'<svg viewBox="{x0:.1f} {y0:.1f} {w:.1f} {h:.1f}" width="{width}" height="{h * width / w:.0f}" role="img" aria-label="Mars ring" '
            f'style="display:block;width:{width}px;max-width:100%;height:auto;margin:6px auto 0">{s}</svg>')
